import pyomo.environ as pyo

DATA = {
    "nodes": [0, 1, 2],
    "arcs": [(0, 1), (0, 2), (1, 0), (1, 2), (2, 0), (2, 1)],
    # net supply under the convention: inflow - outflow = b_n
    # (positive = net supply, negative = net demand)
    "supply": {0: 236, 1: -29, 2: -207},
    "fixed_cost": {
        (0, 1): 3532, (0, 2): 3895,
        (1, 0): 3485, (1, 2): 1845,
        (2, 0): 1291, (2, 1): 1818,
    },
    "var_cost": {
        (0, 1): 45, (0, 2): 49,
        (1, 0): 11, (1, 2): 40,
        (2, 0): 13, (2, 1): 47,
    },
    "capacity": {
        (0, 1): 773, (0, 2): 973,
        (1, 0): 785, (1, 2): 787,
        (2, 0): 602, (2, 1): 766,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=d["nodes"])
    model.A = pyo.Set(initialize=d["arcs"], dimen=2)

    def x_bounds(m, i, j):
        return (0, d["capacity"][(i, j)])

    model.x = pyo.Var(model.A, within=pyo.NonNegativeReals, bounds=x_bounds)
    model.y = pyo.Var(model.A, within=pyo.Binary)

    def obj_rule(m):
        return sum(
            d["fixed_cost"][(i, j)] * m.y[i, j]
            + d["var_cost"][(i, j)] * m.x[i, j]
            for (i, j) in d["arcs"]
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def capacity_rule(m, i, j):
        return m.x[i, j] <= d["capacity"][(i, j)] * m.y[i, j]

    model.capacity_link = pyo.Constraint(model.A, rule=capacity_rule)

    # Flow balance (inflow - outflow = net supply):
    #   sum_i x[i,n] - sum_j x[n,j] == supply[n]
    def balance_rule(m, n):
        inflow = sum(m.x[i, n] for i in d["nodes"] if (i, n) in d["arcs"])
        outflow = sum(m.x[n, j] for j in d["nodes"] if (n, j) in d["arcs"])
        return inflow - outflow == d["supply"][n]

    model.flow_balance = pyo.Constraint(model.N, rule=balance_rule)

    return model


